import { Readable } from "node:stream";
function main(): void {
  const b = Buffer.from("xyz");
  const t = "hello";
  const r = Readable.from([Buffer.from("ab")]);
  r.on("data", (c: Buffer) => { console.log(c.length); });
  r.on("end", () => {
    const copy = Buffer.from(b);
    console.log(copy.length, copy.toString());
    console.log(Buffer.from(t).length, Buffer.from(t, "base64").length, Buffer.concat([b, b]).toString());
    console.log(Buffer.concat([b]).length);
  });
}
